import{_ as a,o as s,c as t,ah as n}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Cashier","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/caissier/index.md","filePath":"src/en/guide/caissier/index.md"}'),r={name:"en/guide/caissier/index.md"};function i(o,e,c,d,p,l){return s(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="cashier" tabindex="-1">Cashier <a class="header-anchor" href="#cashier" aria-label="Permalink to &quot;Cashier&quot;">​</a></h1><p>The cashier&#39;s office manages a student&#39;s financial enrollment once their application has been approved by the registrar&#39;s office: fees due, payments collected, discounts granted, and payment plans. It also tracks the school&#39;s expenses and produces accounting exports. Your pages are in the <strong>Students &amp; admissions</strong> and <strong>Finances</strong> spaces:</p><ul><li><strong><a href="/era-guide/en/guide/caissier/inscriptions-et-paiements.html">Enrollment and payments</a></strong> — enter a new application for a family visiting in person, track fees due per student, collect a payment, print a receipt, set up a payment plan, and view discounts granted.</li><li><strong><a href="/era-guide/en/guide/caissier/export-comptable.html">Accounting export</a></strong> — export payments and expenses as CSV, SYSCOHADA format, or a per-class statement.</li><li><strong><a href="/era-guide/en/guide/caissier/depenses.html">Expenses</a></strong> — record a school expense and track its status.</li></ul><p>To understand how a student reaches the cashier, see the <a href="/era-guide/en/guide/secretariat/">registrar&#39;s office guide</a> — approving an application is what creates the financial enrollment you later find under <strong>Billing</strong>.</p>',4)])])}const h=a(r,[["render",i]]);export{g as __pageData,h as default};
